    "5981": "Fechar",
    "6227": "Os ficheiros necessitam de análise por IA para serem classificados, demasiados ficheiros podem consumir bastante tempo. O modo de trabalho determina se os resultados da análise são armazenados em cache no servidor.",
    "6229": "Transferir diretórios, recursos de rede, livros eletrónicos, banda desenhada, música e outros ficheiros públicos.",
    "6230": "Os seus resultados de análise são apenas guardados localmente, não são armazenados em cache no servidor, protegendo assim a soberania dos dados. No entanto, não poderá beneficiar do aumento de velocidade proporcionado pela cache do servidor.",
    "6231": "Trabalhos originais pessoais, fotografias, relatórios financeiros, documentos privados.",
    "6234": "Já organizado, saltando a análise. Para análise obrigatória, por favor crie um diretório de trabalho independente.",
