    "9771": "Outra solução externa para execução local de grandes serviços de modelo, é 20 a 40% mais lenta que o mecanismo de IA integrado do Firefly, mas tem boa compatibilidade de hardware e é recomendada para instalação.",
    "9772": "A plataforma de experiência de modelo fornecida pela NVIDIA hospeda uma variedade de grandes modelos convencionais e atualmente oferece testes gratuitos.",
