    "9784": "SenseTime",
    "9785": "A nova interface diária de grande modelo do SenseTime está atualmente em período beta público e oferece cota de chamadas gratuitas.",
    "9787": "Modelo leve de alto desempenho do SenseTime",
    "9789": "O modelo de raciocínio extremamente rápido do SenseTime",
    "9792": "Modelo de inferência rápida DeepSeek hospedado por SenseTime",
    "9794": "Inscreva-se e obtenha um teste de $ 10, sem necessidade de cartão de crédito. O crédito é válido por 3 meses. Inclui os modelos Jamba Large e Jamba Mini.",
    "9795": "Israel",
    "9800": "Alibaba Cloud Bailian (versão internacional)",
    "9801": "Após o registro, cada modelo Tongyi Qianwen receberá 1 milhão de tokens grátis, válidos por 90 dias (área internacional/Cingapura). Não é necessário cartão de crédito.",
    "9803": "Chave de API de \"teste\" gratuita, sem necessidade de cartão de crédito. 1.000 chamadas de API por mês. Apenas para uso não comercial.",
    "9804": "Canadá",
    "9816": "Plano \"Experimental\" gratuito, sem necessidade de cartão de crédito. Aproximadamente 1 bilhão de tokens por mês. Palavras-chave podem ser usadas para melhorar o modelo.",
    "9825": "IA Zhipu",
    "9826": "Oferece modelos gratuitos para sempre, sem necessidade de cartão de crédito.",
    "9829": "Grátis, sem necessidade de cartão de crédito. Raciocínio extremamente rápido (cerca de 2.600 tokens/s). Limite diário de 1 milhão de Tokens. Limite de contexto de arquivo gratuito de 8K. llama3.1-8b está programado para ser descontinuado em 27 de maio de 2026.",
    "9835": "10.000 neurônios gratuitos todos os dias. A versão gratuita oferece mais de 50 modelos.",
    "9841": "Créditos de prototipagem gratuitos para todos os usuários do GitHub. Contém mais de 45 modelos. Há um limite para uma única solicitação (entrada de 8K/saída de 4K).",
    "9846": "Grátis, sem necessidade de cartão de crédito. Inferência de LPU extremamente rápida.",
    "9851": "Forneça aos usuários gratuitos uma cota mensal de serviço de inferência de 100.000 vezes. Rotas para provedores como Fireworks, Together, Hyperbolic, Nebius, Novita, DeepInfra e muito mais. Suporta milhares de modelos.",
    "9855": "Modelo gratuito, sem necessidade de cartão de crédito. `kilo-auto/free` roteia automaticamente para minimax/minimax-m2.5:free (80%) e stepfun/step-3.5-flash:free (20%).",
    "9857": "Gateway de API perfeito. Não é necessário registro para acesso básico. Suporta mais de 30 modelos. Compatível com GDPR.",
    "9858": "REINO UNIDO.",
    "9862": "ModelScope",
    "9863": "Fornece serviços gratuitos de inferência de API para usuários registrados. Você precisa vincular sua conta Alibaba Cloud e concluir a autenticação com nome real.",
    "9868": "Cadastre-se e ganhe $ 1 em crédito grátis, sem necessidade de cartão de crédito. Mais de 60 modelos de código aberto estão disponíveis por meio de uma API compatível com OpenAI. Com sede na UE.",
    "9869": "Holanda",
    "9872": "Cadastre-se e ganhe $ 5 em crédito grátis, sem necessidade de cartão de crédito. Provedor soberano da UE com data center localizado na Noruega. Sem limites de taxa, sem partidas a frio.",
    "9874": "Gratuito com limites de uso qualitativos. Oferece mais de 400 modelos da biblioteca Ollama. Não compatível com OpenAI SDK, use [API Ollama](https://docs.ollama.com/cloud).",
    "9877": "Terminal de IA da OVHcloud",
    "9878": "Perfil anônimo gratuito (sem chave de API, sem necessidade de registro): Limite de 2 RPM por modelo por IP. Hospedando mais de 40 modelos de peso de código aberto na UE. Compatível com OpenAI SDK.",
    "9882": "Cota diária gratuita de tokens, sem necessidade de cartão de crédito. Projetado para role-playing e criação de histórias.",
    "9885": "O número de solicitações por minuto é limitado a 20. Se a solicitação for muito rápida em um curto período de tempo, o limite de frequência será acionado (você precisa esperar 1 minuto e tentar novamente)",
    "9886": "Cingapura",
