    "20648": "Ativar captura de ecrã da capa para documentos Office",
    "20649": "Suporta a exportação da primeira página de documentos Office como miniatura da capa, mas aumentará significativamente o tempo de extração de conteúdo do Office. O PDF não é afetado. É necessário instalar o LibreOffice.",
    "20650": "Ativo, invocar o LibreOffice para converter a primeira página em miniatura de capa (muito demorado)",
