    "20675": "Precisão do reconhecimento de OCR",
    "20676": "Selecione o nível de precisão do reconhecimento de texto por OCR. O OCR Rápido é adequado para a maioria dos cenários; o OCR de Alta Precisão é mais exato, mas demora um pouco mais de tempo.",
    "20677": "OCR Ultra",
    "20678": "Concluído em 1 a 2 segundos por imagem, adequado para a maioria dos cenários",
    "20679": "OCR de alta precisão",
    "20680": "Concluído em 2 a 4 segundos por imagem, aumentando a precisão do reconhecimento",
    "20681": "Reutilizar dados em nova análise",
    "20682": "Se os ficheiros tiverem atualizações, desative esta opção; caso contrário, se as informações básicas de qualquer ficheiro já existirem, será ignorada a recolha dessas informações básicas, que incluem: tipo de ficheiro, miniatura, metadados e conteúdo do ficheiro",
    "20683": "Acelera a análise, sem recolher novamente as informações da etapa de análise padrão",
    "20684": "Exemplo: Características de coleções de ficheiros consideradas como unidades globais: coleções de ficheiros com sufixo numérico no nome, por exemplo: 1.txt, 2.txt, 3.txt",
    "20686": "Identificação de unidades globais, como ficheiros de séries, álbuns de faixas de áudio e diretórios de projetos, com suporte para palavras-chave de identificação de unidades personalizadas",
    "20687": "Ativar identificação de unidades mínimas",
    "20688": "As seguintes categorias são identificadas de forma obrigatória, sem necessidade de ativação: diretórios do sistema, diretórios de instalação de software, projetos de engenharia, pacotes de jogos, conjuntos de dados/modelos de IA, caches e LFS, ambientes virtuais",
    "20689": "Quando ativado, os diretórios identificados como unidades mínimas passam a ignorar a análise individual de ficheiros",
    "20690": "Ficheiros de série: documentos ou imagens com numeração sequencial (ex.: 01.jpg, 02.jpg, 03.jpg)",
    "20691": "Álbum de áudio: coleção de ficheiros de faixas do mesmo álbum (como .flac, .mp3)",
    "20692": "Projeto de design: projeto de design com ficheiros de projeto e diretórios de recursos (como .prproj, .aep, .blend)",
    "20693": "Dica: após ser desativado, todos os ficheiros serão analisados de forma independente, adequado para cenários em que cada ficheiro requer a geração individual de descrições e etiquetas",
    "20694": "Palavra-chave para identificação de unidades mínimas",
    "20695": "Necessário ativar a chave acima para ter efeito",
    "20696": "Definir que tipo de coleção de ficheiros deve ser considerada uma unidade de todo, ajustando os julgamentos de identificação do modelo",
    "20698": "The toggle above is off; the prompt is not currently in effect.",
    "20699": "Directories identified as minimum units are processed as a whole single file to avoid generating an excessive number of fragmented analysis results.",
    "20701": "É necessário instalar a dependência externa ffprobe",
