    "20716": "Suporta a seleção em múltiplas dimensões para adicionar ou remover em lote etiquetas de ficheiros-alvo, complementando o perfil semântico dos ficheiros.",
    "20717": "Verificação de duplicados segura",
    "20718": "Baseado na análise inteligente do FireFly Omni, limpa com segurança ficheiros redundantes e duplicados; todas as eliminações são movidas para a Lixeira do sistema.",
    "20719": "Escolher o fluxo principal de organização ou pré-processamento",
    "20720": "Recomenda-se avançar diretamente para [Organização em Lote] para que a IA crie a hierarquia de diretórios; também pode utilizar ferramentas satélite antes da organização para renomear de forma padronizada, adicionar etiquetas ou realizar verificação de duplicados com limpeza segura.",
