    "20723": "Iniciar organização em lote",
    "20724": "Com base na análise inteligente multidimensional por IA ou em regras de diretório virtual, os ficheiros selecionados são categorizados de forma inteligente e exportados para um diretório físico ou para um novo diretório virtual. Sem operações preliminares complexas, gere diretamente um sumário de ficheiros eficiente.",
