    "22216": "Organize apenas os primeiros {limit} arquivos",
    "22217": "Não bloqueia o processo",
    "22218": "Os primeiros arquivos {limit} são carregados primeiro para clustering de IA e derivação de classificação. Os arquivos {rest} restantes são deixados como estão e podem ser classificados em lotes posteriormente.",
    "22219": "Entre no processo de classificação imediatamente, sem necessidade de selecionar manualmente um por um",
    "22220": "Vá para a página \"Analisado\" para filtrar manualmente",
    "22221": "Selecione a coleção de arquivos de destino que deseja organizar por combinação livre de rótulos de dimensão, categorias de arquivo (como apenas imagens/documentos) ou subdiretórios especificados.",
