    "22228": "O número de arquivos a serem classificados excede o limite superior ({limit}). Vá para a página \"Analisado\" para verificar os arquivos e tente novamente.",
    "22229": "Se houver muitos arquivos não classificados ({total}), a IA dará prioridade para encontrar os 200 principais arquivos de alto potencial.",
    "22246": "Formato de imagem não suportado",
    "22247": "Eu encontrei uma ferramenta de IA gratuita de código aberto super fácil de usar \"Firefly AI Folder\", que pode organizar a área de trabalho bagunçada, diretório de download, etc. com um clique, pesquisar conteúdo de imagem, texto, áudio e vídeo em linguagem natural em segundos, e o vídeo pode até ser posicionado em um intervalo de tempo específico, e a IA categoriza/renomeia/marca/descreve/miniaturas/arquiva/limpa automaticamente! Utilize recursos locais de IA para garantir a privacidade. Nenhuma placa gráfica é necessária. Notebooks finos e leves com pouca memória podem executar IA com alta qualidade. A tecnologia inovadora de organização de diretório virtual garante a segurança dos arquivos. Venha e experimente!",
    "22248": "Não foi possível determinar os arquivos a serem classificados. Selecione novamente e tente novamente.",
    "22249": "{count} seleções não organizadas (não analisadas, expiradas ou diretórios) excluídas",
