    "22258": "Atualmente em modo de classificação completo ({count} itens no total, excedendo {limit} itens recomendados para um único lote). Um único cálculo em grande escala aumentará significativamente o consumo de tempo e memória da IA:",
    "22259": "Um único cálculo extremamente grande aumentará significativamente o uso de memória e o tempo de resposta da IA ​​(complexidade O(N²)), e a granularidade do clustering de diretórios poderá se tornar mais ampla.",
