    "22316": "Tais como: classificação por ano e finanças, arquivamento de documentos de projetos...",
    "22320": "Exemplos: Adicione mais pontos às histórias de comédia; reduzir o peso dos indicadores técnicos; a descrição do conteúdo multimodal concentra-se nas relações entre os personagens, traduzida como {activeLanguage}",
    "22321": "Exemplo: nomes de arquivos inteligentes precisam ser traduzidos para {activeLanguage}. Podem ser geradas no máximo 20 tags, e cada tag não deve exceder 2 palavras. Pelo menos uma tag deve ser extraída do nome do arquivo, e as demais devem ser extraídas deste conjunto: [Felicidade, Dor, Ressentimento,...]",
    "22334": "[Reconstrução do mecanismo de IA] O mecanismo de IA básico integrado está pronto para uso imediato, com mecanismo de IA avançado Firecore/nuvem opcional para aprimorar a análise sob demanda.",
    "22335": "[Amigável ao computador de baixa configuração] Reconstrua a arquitetura de IA de alta velocidade com base na inferência da CPU, funcionando perfeitamente em dispositivos com pouca memória sem placas gráficas independentes",
    "22336": "[Motor Firecore AI independente] Pode ser executado independentemente do programa principal para fornecer recursos de IA para aplicativos de terceiros",
    "22337": "[Pesquisa Semântica Multimídia] Imagens, áudios e vídeos suportam recuperação de linguagem natural e pesquisam conteúdo por semântica, imagens e vozes",
    "22338": "[Fala para texto ASR] Transcreva rapidamente conversas de áudio e vídeo em texto para fácil recuperação e arquivamento",
    "22339": "[Speech Synthesis TTS] Conversão de texto para fala, mais de 50 sons integrados, suporta clonagem de som de 3 segundos e lê romances de documentos em voz alta",
    "22340": "[Atualização de tag de arquivo] Enriqueça os tipos de tags de fatos, as tags são mais precisas e interpretáveis, e a árvore de tags suporta 10 níveis de expansão",
    "22341": "[Otimização do material do criador] Para designers e auto-mídia, otimização especial da classificação do material de áudio, vídeo e imagem",
    "22342": "[Detecção aprimorada de conteúdo sensível] Identifique segmentadamente conteúdo pornográfico, violento, terrorista, político, abusivo, sangrento e outros conteúdos ilegais e suas subcategorias",
    "22343": "[Cinco modos principais de classificação de lote] Plano de identidade / clustering inteligente / diretório gerado por IA externa / árvore de diretório de derivação de arquivo / árvore de diretório personalizada, processando milhares de arquivos em segundos",
    "22344": "[Identity Blueprint (recomendado)] Selecione funções do setor, otimização em quatro estágios e classifique todos os arquivos em milissegundos no lado do cliente",
    "22345": "[Clustering inteligente] Clustering não supervisionado HAC final, gera árvores de diretórios em milissegundos, classifica todos os arquivos em segundos e suporta ajuste fino em tempo real",
    "22346": "[Diretório externo gerado por IA] Copie palavras de prompt para Doubao, Kimi, ChatGPT com um clique e visualize e organize os resultados em tempo real",
    "22347": "[Derivar árvores de diretórios de arquivos] O mecanismo avançado de IA gera 3 conjuntos de candidatos a diretório por vez e a classificação automática é selecionada",
    "22348": "[Árvore de diretórios personalizada] Cole o diretório Markdown, visualize duas colunas em tempo real e crie regras de organização exclusivas",
    "22349": "[Otimização detalhada da interface do usuário] Reconstrua a estrutura da página de configuração, adicione um novo guia e entrada de ajuda e torne a operação mais intuitiva.",
    "22350": "Ocorre uma exceção na interface",
    "22351": "O processo de renderização da interface foi encerrado e o aplicativo não foi retomado automaticamente. Reinicie o aplicativo e tente novamente.",
