    "23350": "Detecte arquivos novos, modificados e excluídos no diretório atual em tempo real. Após a abertura, novos arquivos serão sincronizados automaticamente e adicionados à fila de análise inteligente de IA.",
    "23351": "Nova verificação e detecção de alterações",
    "23352": "Execute uma comparação completa dos arquivos do disco físico para verificar se há novos arquivos ou alterações adicionadas off-line e, opcionalmente, envie-os para a fila de análise.",
    "23353": "Digitalizar novamente",
