    "23370": "Redefinir dados de análise de catálogo com segurança",
    "23371": "Limpe as tags AI, o cache do storyboard e o índice de texto de todos os arquivos no diretório atual. Protegidos pelo mecanismo de proteção órfã entre espaços de trabalho, os arquivos compartilhados nunca serão danificados acidentalmente.",
    "23372": "Redefinir dados...",
