    "28427": "Copiar palavra de prompt de acesso",
    "28428": "Permissões mínimas e instruções de segurança para interfaces locais",
    "28429": "A interface aberta local é apenas para agentes autorizados locais consultarem metadados de análise de arquivos e enviarem rascunhos de edição multidimensionais. Não tem autoridade para reescrever ou excluir diretamente arquivos físicos. Todos os planos de organização enviados por agentes externos são enviados como rascunhos e devem ser explicitamente confirmados por você no desktop antes de serem implementados.",
    "28430": "A palavra de prompt de unidade mínima personalizada depende da capacidade de compreensão do modelo de idioma do mecanismo generativo e atualmente não está habilitada.",
    "28431": "Mecanismo de pesquisa",
    "28432": "Escolha diferentes modos de acordo com suas necessidades. A análise abrangente leva mais tempo, mas tem a maior precisão; a análise padrão é a mais rápida. A análise aprimorada e a análise abrangente exigem que o mecanismo generativo esteja ligado.",
    "28433": "Aquisição em alta velocidade de tags de arquivos, nomes de arquivos inteligentes e resumos baseados em mecanismo de busca",
    "28434": "[Análise padrão] + Mecanismo generativo aprimora nomes e descrições de arquivos inteligentes e tags complementares",
