    "28461": "Recursos opcionais",
    "28468": "Repetir",
    "28471": "Retornar",
    "28475": "A derivação de árvores de diretórios de arquivos requer suporte para o mecanismo generativo. Por favor, vá para \"Configurações -> Mecanismo Generativo\" para habilitá-lo.",
    "28476": "Motor generativo necessário",
    "28534": "Regras globais de arquivo de exclusão",
    "28535": "Configure arquivos que não são exibidos no diretório real para que não entrem na análise de IA para melhorar a eficiência da análise e oferecer suporte à verificação e limpeza de duplicação em lote para proteger esses arquivos excluídos.",
    "28536": "O cérebro de pesquisa central de todo o software (escolha um dos dois). A alteração do mecanismo restabelecerá automaticamente o índice de pesquisa de todos os arquivos.",
    "28537": "Entenda o conteúdo falado em áudio e vídeo e converta-o em legendas de texto. Você pode pesquisar arquivos diretamente por diálogo.",
    "28538": "Leia o documento para você com uma bela voz de pessoa real e suporte a leitura off-line e a audição de livros e materiais com fones de ouvido.",
    "28539": "Identifique e marque automaticamente fotos privadas e conteúdo confidencial para evitar constrangimento ao transmitir ou visualizar em público.",
    "28540": "Você pode ver o conteúdo de arquivos especiais, como arquivos compactados, sem descompactá-los, e pesquisar diretamente informações internas.",
    "28541": "Widgets de extensão inteligentes ricos, você pode abrir livremente uma variedade deles para auxiliar na organização e análise diária.",
    "28551": "Primeiros socorros na área de trabalho do computador e fluxo de limpeza de desordem",
    "28552": "Projetado especificamente para desktops de computador, ele fornece distribuição panorâmica de tarefas atuais, rascunhos de trabalho, capturas de tela temporárias, materiais a serem arquivados e pacotes de instalação, além de arquivar com segurança desktops antigos.",
    "28554": "Baixe o desvio panorâmico do diretório e o fluxo de limpeza",
    "28555": "Para o diretório misto de navegadores e ferramentas de download, o Panorama distribui pacotes de instalação de aplicativos, documentos diários de escritório, fotos, áudio e vídeo e imagens de arquivo compactadas e define um período de proteção de limpeza de expiração.",
