    "31331": "Mecanismo AI Light Clássico (Luz Clássica)",
    "31332": "Mecanismo básico de IA",
    "31333": "[Encontre arquivos e imagens por significado] Pesquise rapidamente fotos e documentos com base no significado geral de sua descrição. Ocupando muito pouca memória, até mesmo computadores antigos e notebooks finos e leves de baixo custo podem funcionar sem problemas. Não suporta áudio e vídeo",
    "31334": "Requisitos de configuração extremamente baixos · A primeira escolha para computadores antigos e laptops finos e leves",
    "31335": "Mecanismo de IA unificado totalmente modal (Gemma Unified)",
    "31336": "[Cérebro de pesquisa abrangente e mais inteligente] Ele pode compreender frases complexas, imagens, áudios e vídeos com mais profundidade e precisão, e pode entender melhor seus pensamentos ao procurar coisas. Recomendado para computadores com 8 GB ou mais de memória.",
    "31337": "Configuração recomendada · Memória do computador 8 GB ou superior",
    "31338": "Mecanismo gerador de CPU leve (Pocket CPU)",
    "31339": "[Padrão em laptops de escritório finos e leves] Suporta polimento aprofundado de nome de arquivo inteligente, extração de descrição e análise aprofundada de conteúdo. Este plug-in não é necessário se o mecanismo Firecore estiver habilitado.",
    "31340": "Requisitos de configuração extremamente baixos · Operação pura da CPU",
    "31341": "Conteúdo confidencial e identificação de classificação NSFW",
    "31342": "Extração de conteúdo de arquivo",
    "31343": "[Marcação de imagem e texto privada e sensível] Identifique automaticamente imagens e documentos privados e confidenciais/texto AIGC contendo descrições explícitas e confidenciais e marque-os para evitar constrangimento ao visualizá-los em uma tela. Todos os computadores funcionam extremamente rápido.",
    "31344": "Requisitos mínimos de configuração · Processamento extremamente rápido",
    "31345": "Reconhecimento de fala e extração de legendas ASR (SenseVoice)",
    "31346": "[Converta automaticamente gravações e vídeos em texto] Entenda o conteúdo da fala em vídeos e gravações e extraia legendas. Você pode pesquisar diretamente por “quem disse uma determinada frase”. Ele consome mais poder de computação, portanto, recomenda-se 16 GB de memória ou placa gráfica.",
    "31347": "É necessária mais capacidade de computação · Memória de 16 GB ou placa gráfica recomendada",
    "31348": "Leitura de clone de voz personalizada (Moss-TTS)",
    "31349": "[Suporta clonagem de vozes exclusivas] Extrator de som integrado, carregue uma gravação para clonar vozes exclusivas para ler artigos. Suporta mais de 50 sons escolhidos a dedo e clones personalizados.",
    "31350": "Baixos requisitos de configuração · Computador comum para uma pronúncia suave",
    "31351": "Leitura de voz extremamente rápida e leve (M5-TTS)",
    "31352": "[Leitura extremamente rápida e com economia de energia] Pressione play e o som começará instantaneamente em milissegundos. Possui mais de 50 vozes ricas e de alta qualidade integradas, e documentos longos podem ser lidos em voz alta sem problemas. Notebooks finos e leves comuns funcionam perfeitamente.",
    "31353": "Requisitos de configuração extremamente baixos · Pronúncia suave para notebooks finos e leves comuns",
    "31354": "Estúdio de mapeamento local",
    "31355": "[Desenhe imagens localmente em seu computador] Digite uma frase para desenhar lindas imagens localmente sem gastar um centavo. Requer uma placa gráfica discreta melhor.",
    "31356": "Configuração superior · Requer placa gráfica discreta",
    "31357": "Perspectiva de pacote compactado e analisador de profundidade",
    "31358": "[Pesquise o pacote compactado diretamente sem descompactar] Você pode visualizar e pesquisar diretamente o conteúdo do arquivo dentro do zip/rar sem descompactá-lo, sem qualquer carga adicional do computador.",
