    "31654": "Você pode personalizar as preferências de execução do plug-in por meio das configurações abaixo. Uma vez salvo, ele entrará em vigor imediatamente e será mantido.",
    "31655": "Insira o conteúdo de configuração do parâmetro do plug-in (como {\"key\": \"value\"})",
    "31656": "Slot",
    "31659": "Verificando plug-in",
    "31660": "O modelo está danificado e precisa ser reparado",
