    "31666": "Desativar",
    "31667": "Habilitar",
    "31668": "Mudará automaticamente para outros mecanismos instalados e desinstalará o mecanismo atual",
    "31669": "Desinstalar módulo de extensão",
    "31670": "Trocar e desinstalar",
    "31671": "Confirme a troca e desinstale o mecanismo atual",
    "31672": "Confirme para desinstalar o plugin",
    "31673": "Ele mudará automaticamente para outro mecanismo instalado do mesmo tipo e removerá os ativos atuais do mecanismo. Estima-se que aproximadamente {size} espaço em disco será liberado. Tem certeza de que deseja desinstalar?",
    "31674": "O plug-in e seus ativos de modelo serão removidos do seu computador, liberando aproximadamente {size} espaço em disco. Tem certeza de que deseja desinstalar?",
    "31675": "Confirme a troca e desinstale",
    "31676": "Confirmar desinstalação",
    "31677": "O modelo off-line leve e de alta fidelidade suporta alto-falante rico e leitura natural em vários idiomas",
    "31678": "Navegue pela biblioteca de sons em destaque, ouça e adicione seus sons favoritos à sua coleção rápida.",
    "31679": "As regras de inclusão e as regras de exclusão podem ser definidas ao mesmo tempo e entrar em vigor sobrepostas.",
    "31680": "As regras de inclusão foram liberadas e agora todas as quantidades são liberadas de acordo com as regras de exclusão",
    "31681": "As regras de inclusão e as regras de exclusão podem ser definidas ao mesmo tempo e entrar em vigor em conjunto; o sistema primeiro excluirá, depois filtrará de acordo com as regras de inclusão e, finalmente, permitirá os arquivos restantes.",
    "31682": "Salvar regras de inclusão e exclusão",
    "31683": "A modificação das regras de inclusão e exclusão afeta apenas os arquivos mostrados no diretório real e não afeta nenhum dos arquivos físicos originais no disco do seu computador.",
    "31684": "Regras de acesso a arquivos (podem ser definidas ao mesmo tempo)",
    "31685": "A sobreposição Incluir + Excluir entra em vigor",
    "31686": "As regras de inclusão e as regras de exclusão são dois conjuntos independentes de configurações que podem ser definidos ao mesmo tempo e sobrepostos para entrar em vigor. Não há necessidade de escolher um entre os dois. O sistema determina na seguinte ordem fixa:",
    "31687": "1. Exclusão total do sistema",
    "31688": "2. Exclusões específicas de diretório",
    "31689": "3. Incluir regras",
    "31690": "4. Liberar por padrão",
    "31691": "Deixe a regra de inclusão em branco para indicar que não há restrição de formato e todas as extensões serão permitidas, exceto exclusões; após o preenchimento, somente serão permitidas essas extensões. As regras de exclusão sempre entram em vigor primeiro, e arquivos como miniaturas e diretórios de cache podem ser excluídos com precisão sob regras de inclusão amplas.",
    "31692": "Deixe a regra de inclusão em branco: os arquivos restantes serão liberados de acordo com a regra de exclusão",
    "31693": "A ser medido",
    "31694": "Atualmente não há regras de inclusão definidas: há arquivos {totalFiles} no diretório. Exceto os arquivos atingidos por exclusões rígidas do sistema e regras de exclusão específicas de diretório, os arquivos {included} restantes serão incluídos na análise de IA.",
    "31695": "Nenhuma regra de inclusão está definida atualmente: exceto para arquivos atingidos por exclusões severas do sistema e regras de exclusão específicas de diretório, todos os outros arquivos serão incluídos na indexação e análise de IA. As regras de inclusão podem ser adicionadas a qualquer momento e entrarão em vigor ao mesmo tempo que as regras de exclusão.",
    "31696": "Modelo nomeado",
