    "31720": "Selecionado, continue para a próxima etapa",
    "31721": "Clique neste cartão para selecioná-lo",
    "31722": "Os dois métodos são apenas maneiras diferentes de obter o plug-in. Após a instalação, as funções são exatamente as mesmas; você pode adicioná-los ou subtraí-los a qualquer momento no centro de plug-ins no futuro, para que não precise se preocupar em selecionar o errado agora.",
    "31723": "Próxima etapa",
    "31725": "A detetar...",
    "31726": "Com base na biblioteca de arquivos verificada ({total} arquivos no total), espera-se que {included} arquivos de formato de destino (aproximadamente {inPct}%) sejam incluídos com precisão e os {excluded} arquivos restantes de regras de não inclusão (aproximadamente {outPct}%) sejam automaticamente excluídos.",
    "31727": "Suporte de áudio e vídeo",
    "31730": "Não suporta áudio e vídeo",
    "31734": "A pasta selecionada não atende aos requisitos, selecione novamente",
    "31735": "Esta pasta não pode ser definida como diretório de instalação por enquanto. Por favor use o diretório padrão; você pode alterá-lo nas configurações após entrar na interface principal.",
    "31736": "Selecione o diretório de instalação do plug-in",
    "31737": "Selecione uma pasta de armazenamento de longo prazo para o modelo cerebral de IA e componentes de expansão funcional. Você também pode alterá-lo nas configurações posteriormente.",
    "31738": "Os modelos e plug-ins de IA são grandes. Certifique-se de que o disco selecionado tenha espaço livre suficiente. Recomenda-se reservar pelo menos 10GB; ele será interceptado automaticamente quando não houver espaço suficiente.",
    "31739": "Recomenda-se escolher uma pasta em uma unidade de estado sólido (SSD). O carregamento do modelo e a pesquisa de arquivos serão significativamente mais rápidos. Discos rígidos mecânicos também podem ser usados, mas o primeiro carregamento é mais lento.",
    "31740": "Use um caminho em inglês puro, não contenha caracteres chineses ou espaços e não selecione uma pasta do sistema ou diretório raiz do disco.",
    "31741": "Diretório de armazenamento de plug-in e modelo",
    "31742": "Uma pasta local que armazena modelos cerebrais de IA e componentes de expansão funcional",
    "31743": "O caminho de armazenamento padrão atual do plug-in contém caracteres chineses, o que pode afetar a operação estável de alguns modelos de IA. É altamente recomendável mudar para um diretório de disco em inglês puro.",
